payload.arguments:
{"cmd": "$ports = @(1..1024) + @(11311,11811,2018,5000,5900,7400,7401,7402,7410,8080,8081,8888,9090,9091,10000,1883,3000,22,80)
function Scan($ip,$ports){
  $open=@()
  for ($i=0; $i -lt $ports.Count; $i+=300) {
    $batch = $ports[$i..([math]::Min($i+299,$ports.Count-1))]
    $cl=@()
    foreach ($p in $batch) { $c=New-Object System.Net.Sockets.TcpClient; try{ $null=$c.ConnectAsync($ip,$p) }catch{}; $cl += [pscustomobject]@{Port=$p;C=$c} }
    Start-Sleep -Milliseconds 1000
    foreach ($o in $cl) { if ($o.C.Connected) { $open += $o.Port }; try{$o.C.Close()}catch{} }
  }
  $open | Sort-Object -Unique
}
Write-Output "=== 192.168.1.108 OPEN PORTS ==="; $r = Scan "192.168.1.108" $ports; if($r){ $r -join ', ' } else { '(none)' }
Write-Output "=== 192.168.1.254 OPEN PORTS ==="; $r2 = Scan "192.168.1.254" $ports; if($r2){ $r2 -join ', ' } else { '(none)' }", "timeout_ms": 60000}

